try {
  render();
  const cards=$('cards');
  if(!cards || !cards.innerHTML.includes('class="card"')) throw new Error('Summary cards did not render');
  const indicator=document.getElementById('data-health');
  if(indicator) indicator.textContent=`Data loaded · ${DATA.meta.submissionRows} source submissions · ${new Set(DATA.records.map(x=>x.ref)).size} represented by parsed records · ${DATA.meta.section2Records} Section 2 records`;
} catch(err) {
  console.error('UOL dashboard render error:',err);
  const indicator=document.getElementById('data-health');
  if(indicator) {indicator.textContent='Display error: '+err.message+' — please extract the ZIP and open this index.html';if(indicator.style) indicator.style.color='#9d2637';}
  const panel=document.getElementById('table');
  if(panel) panel.innerHTML='<p style="padding:20px;color:#a32636">The audit data is packaged, but the view could not render. '+esc(err.message)+'</p>';
}
